inline uint32_t event_class_hash(const char* s) {
    uint32_t h = 0x811C9DC5u;
    for (; *s; ++s) { h ^= (uint8_t)*s; h *= 0x01000193u; }
    return h;
}

// true: the event may be resolved by each player on its own (own cats, own option).
inline bool event_class_independent(const char* name) {
    if (!name || !name[0]) return false;
    const uint32_t h = event_class_hash(name);
    uint32_t lo = 0, hi = (uint32_t)(sizeof(kIndepEventHashes) / sizeof(kIndepEventHashes[0]));
    while (lo < hi) { const uint32_t mid = (lo + hi) / 2; if (kIndepEventHashes[mid] < h) lo = mid + 1; else hi = mid; }
    return lo < sizeof(kIndepEventHashes) / sizeof(kIndepEventHashes[0]) && kIndepEventHashes[lo] == h;
}

