inline const char* event_name_by_hash(uint32_t h) {
    uint32_t lo = 0, hi = (uint32_t)(sizeof(kEventNames) / sizeof(kEventNames[0]));
    while (lo < hi) { const uint32_t mid = (lo + hi) / 2; if (kEventNames[mid].hash < h) lo = mid + 1; else hi = mid; }
    return lo < sizeof(kEventNames) / sizeof(kEventNames[0]) && kEventNames[lo].hash == h ? kEventNames[lo].name : nullptr;
}

